#if APP_TESTS
using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Windows;using System.Windows.Controls;using System.Windows.Controls.Primitives;using System.Windows.Input;
namespace FileCompass {
 internal static class CascadeNavigationTests {
  static IEnumerable<MenuItem> All(ItemsControl owner){foreach(var item in owner.Items.OfType<MenuItem>()){yield return item;foreach(var child in All(item))yield return child;}}
  static void Pump(){NavigationTests.Wait(System.Threading.Tasks.Task.Delay(100));}
  static void Draw(FrameworkElement element,string path){element.UpdateLayout();var bitmap=new System.Windows.Media.Imaging.RenderTargetBitmap((int)Math.Ceiling(element.ActualWidth),(int)Math.Ceiling(element.ActualHeight),96,96,System.Windows.Media.PixelFormats.Pbgra32);bitmap.Render(element);var encoder=new System.Windows.Media.Imaging.PngBitmapEncoder();encoder.Frames.Add(System.Windows.Media.Imaging.BitmapFrame.Create(bitmap));using(var stream=File.Create(path))encoder.Save(stream);}
  static void DrawCascade(Window main,MenuItem item,string path){var popup=(Popup)item.Template.FindName("PART_Popup",item);var child=(FrameworkElement)popup.Child;var at=item.TranslatePoint(new Point(item.ActualWidth+popup.HorizontalOffset,popup.VerticalOffset),main);var visual=new System.Windows.Media.DrawingVisual();using(var dc=visual.RenderOpen()){dc.DrawRectangle(new System.Windows.Media.VisualBrush(main),null,new Rect(0,0,main.ActualWidth,main.ActualHeight));dc.DrawRectangle(new System.Windows.Media.VisualBrush(child),null,new Rect(at.X,at.Y,child.ActualWidth,child.ActualHeight));}var bitmap=new System.Windows.Media.Imaging.RenderTargetBitmap((int)Math.Ceiling(main.ActualWidth),(int)Math.Ceiling(main.ActualHeight),96,96,System.Windows.Media.PixelFormats.Pbgra32);bitmap.Render(visual);var encoder=new System.Windows.Media.Imaging.PngBitmapEncoder();encoder.Frames.Add(System.Windows.Media.Imaging.BitmapFrame.Create(bitmap));using(var stream=File.Create(path))encoder.Save(stream);}
  internal static int Run(string path){Directory.CreateDirectory(path);var log=new List<string>();MainWindow main=null;Window sample=null;try{
   Action<bool,string> check=delegate(bool ok,string text){if(!ok)throw new Exception(text);log.Add(text);};L.ChangeLanguage("cs");
   main=new MainWindow(path,new ProgramSettings{AutoRefresh=false}){Left=-18000,Top=-18000,Width=1440,Height=920,WindowStartupLocation=WindowStartupLocation.Manual,ShowActivated=false};main.Show();NavigationTests.WaitPanels(main);main.ToggleFluentDrawer();Pump();main.UpdateLayout();
   var drawer=FluentUiTests.Children<Border>(main).Single(x=>Convert.ToString(x.Tag)=="fluent-drawer");var menu=FluentUiTests.Children<Menu>(drawer).Single(x=>Convert.ToString(x.Tag)=="cascade-menu");var roots=menu.Items.OfType<MenuItem>().ToArray();
   check(roots.Length>=11,"all original categories plus promoted Tools remain available");
   for(int i=1;i<roots.Length;i++)check(roots[i].TranslatePoint(new Point(),drawer).Y>=roots[i-1].TranslatePoint(new Point(0,roots[i-1].ActualHeight),drawer).Y,"categories are separate vertical rows: "+roots[i].Header);
   foreach(string key in new[]{"media.menu","operation.tools","connections.title","action.help","menu.file","menu.commands","menu.configuration"})check(roots.Any(x=>Convert.ToString(x.Header)==L.Text(key)),"category is accessible: "+L.Text(key));
   foreach(string key in new[]{"media.convertImages","media.convertAudio","analyzer.title","smart.title","ext.title","queue.copyTitle","queue.restoreSaved","action.settings","workspace.title","projection.basket"})check(All(menu).Any(x=>Convert.ToString(x.Header)==L.Text(key)),"command retained: "+L.Text(key));
   main.VerifyCascadeCommands(check,FluentUiTests.Children<Menu>(drawer).SelectMany(All).ToArray());
   foreach(var root in roots){root.IsSubmenuOpen=true;Pump();root.ApplyTemplate();var popup=root.Template.FindName("PART_Popup",root) as Popup;check(popup!=null&&popup.IsOpen&&popup.Placement==PlacementMode.Right,"category opens a native right-hand flyout: "+root.Header);check(popup.Child.RenderSize.Width>150&&popup.Child.RenderSize.Height>20,"flyout content is measured: "+root.Header);if(Convert.ToString(root.Header)==L.Text("media.menu"))Draw((FrameworkElement)popup.Child,Path.Combine(path,"media.png"));root.IsSubmenuOpen=false;}
   var file=roots.First(x=>Convert.ToString(x.Header)==L.Text("menu.file"));file.IsSubmenuOpen=true;Pump();var nested=file.Items.OfType<MenuItem>().First(x=>x.HasItems);nested.IsSubmenuOpen=true;Pump();var nestedPopup=(Popup)nested.Template.FindName("PART_Popup",nested);check(nestedPopup.IsOpen&&nestedPopup.Placement==PlacementMode.Right,"nested submenu also opens to the right");Draw((FrameworkElement)nestedPopup.Child,Path.Combine(path,"nested.png"));
   NextStageTests.Draw(main,Path.Combine(path,"sidebar.png"));Draw((FrameworkElement)((Popup)file.Template.FindName("PART_Popup",file)).Child,Path.Combine(path,"file.png"));nested.IsSubmenuOpen=false;Pump();DrawCascade(main,file,Path.Combine(path,"cascade-preview.png"));
   main.CloseFluentDrawer();check(!drawer.IsVisible&&roots.All(x=>!x.IsSubmenuOpen)&&!nested.IsSubmenuOpen,"closing drawer dismisses every popup");main.ToggleFluentDrawer();Pump();check(drawer.IsVisible&&roots.All(x=>!x.IsSubmenuOpen),"reopening starts with all categories closed");
   var esc=new KeyEventArgs(Keyboard.PrimaryDevice,PresentationSource.FromVisual(main),0,Key.Escape){RoutedEvent=Keyboard.PreviewKeyDownEvent};main.RaiseEvent(esc);check(!drawer.IsVisible&&esc.Handled,"Escape closes drawer and handles the key");
   var original=new MenuItem{Header="Synthetic root"};var leaf=new MenuItem{Header="Checked action",IsCheckable=true,InputGestureText="Ctrl+K"};bool invoked=false,closed=false,dynamic=false;leaf.Click+=delegate{invoked=closed;};original.Items.Add(leaf);var disabled=new MenuItem{Header="Disabled",IsEnabled=false};original.Items.Add(disabled);original.SubmenuOpened+=delegate{if(!dynamic){dynamic=true;original.Items.Add(new MenuItem{Header="Added dynamically"});}};
   var other=new MenuItem{Header="Other category"};other.Items.Add(new MenuItem{Header="Other command"});var rendered=CascadeNavigation.Build(new[]{original,other},delegate{closed=true;});sample=new Window{Width=260,Height=240,Left=-18000,Top=-18000,Content=new Border{Tag="fluent-drawer",Background=FluentColors.Navigation,Child=rendered}};sample.Show();original.IsSubmenuOpen=true;Pump();check(original.Items.Count==3&&((MenuItem)original.Items[2]).Style==CascadeNavigation.RowStyle,"dynamic submenu items receive the cascade presentation");check(!disabled.IsEnabled&&leaf.InputGestureText=="Ctrl+K","disabled states and gesture labels are preserved");
   original.IsSubmenuOpen=false;sample.Activate();original.Focus();var down=new KeyEventArgs(Keyboard.PrimaryDevice,PresentationSource.FromVisual(sample),0,Key.Down){RoutedEvent=Keyboard.PreviewKeyDownEvent};original.RaiseEvent(down);Pump();check(down.Handled&&other.IsKeyboardFocused,"Down arrow moves to next vertical category");var up=new KeyEventArgs(Keyboard.PrimaryDevice,PresentationSource.FromVisual(sample),0,Key.Up){RoutedEvent=Keyboard.PreviewKeyDownEvent};other.RaiseEvent(up);Pump();check(up.Handled&&original.IsKeyboardFocused,"Up arrow moves to previous vertical category");var right=new KeyEventArgs(Keyboard.PrimaryDevice,PresentationSource.FromVisual(sample),0,Key.Right){RoutedEvent=Keyboard.PreviewKeyDownEvent};original.RaiseEvent(right);Pump();check(right.Handled&&original.IsSubmenuOpen&&leaf.IsKeyboardFocused,"Right arrow opens category and focuses its first command");
   var left=new KeyEventArgs(Keyboard.PrimaryDevice,PresentationSource.FromVisual(sample),0,Key.Left){RoutedEvent=Keyboard.PreviewKeyDownEvent};leaf.RaiseEvent(left);Pump();check(left.Handled&&!original.IsSubmenuOpen&&original.IsKeyboardFocused,"Left arrow returns from commands to the category");original.IsSubmenuOpen=true;Pump();
   var peer=new System.Windows.Automation.Peers.MenuItemAutomationPeer(leaf);var provider=peer.GetPattern(System.Windows.Automation.Peers.PatternInterface.Invoke);foreach(var contract in provider.GetType().GetInterfaces())if(contract.FullName=="System.Windows.Automation.Provider.IInvokeProvider")contract.GetMethod("Invoke").Invoke(provider,null);Pump();check(leaf.IsChecked&&invoked&&closed,"native checked action runs original handler after drawer closes");
   main.Width=960;main.Height=660;main.ToggleFluentDrawer();Pump();main.UpdateLayout();var scroll=FluentUiTests.Children<ScrollViewer>(drawer).Single(x=>Convert.ToString(x.Tag)=="drawer-scroll");scroll.ScrollToEnd();Pump();check(roots.Last().TranslatePoint(new Point(0,roots.Last().ActualHeight),drawer).Y<=drawer.ActualHeight,"last category stays reachable in a smaller window: offset="+scroll.VerticalOffset+", extent="+scroll.ExtentHeight+", viewport="+scroll.ViewportHeight+", visible="+drawer.IsVisible+", end="+roots.Last().TranslatePoint(new Point(0,roots.Last().ActualHeight),drawer).Y+", drawer="+drawer.ActualHeight);var tools=roots.Single(x=>Convert.ToString(x.Header)==L.Text("operation.tools"));tools.IsSubmenuOpen=true;Pump();check(((Popup)tools.Template.FindName("PART_Popup",tools)).IsOpen,"tools flyout remains usable in a smaller window");main.CloseFluentDrawer();
   sample.Close();sample=null;main.Close();main=null;File.WriteAllLines(Path.Combine(path,"result.txt"),log.Concat(new[]{"PASS: "+log.Count}));return 0;
  }catch(Exception ex){File.WriteAllLines(Path.Combine(path,"result.txt"),log.Concat(new[]{"FAIL: "+ex}));return 1;}finally{if(sample!=null)sample.Close();if(main!=null)main.Close();}}
 }
 public partial class MainWindow {
  internal void VerifyCascadeCommands(Action<bool,string> check,MenuItem[] items){foreach(var command in releaseCommands){check(items.Contains(command.Item),"registered command remains the original menu instance: "+command.Id);foreach(var mirror in command.Mirrors)check(items.Contains(mirror),"duplicate command entry remains accessible: "+command.Id);}}
 }
}
#endif
